contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 val) public {
        require(val >= 0);

        uint256 minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        bool setReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        assert(
            !initReverted &&
            setReverted &&
            c.MinSum() == minBefore
        );
    }
}

