pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val) internal {
        vm.assume(val >= 0);
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        bool setReverted;
        try c.SetMinSum(val) {
            setReverted = false;
        } catch {
            setReverted = true;
        }
        assertTrue(!initReverted &&
            setReverted &&
            c.MinSum() == minBefore);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
